def component_labels(g, value=1, diag=False):
    h,w=len(g),len(g[0]); neigh=[(dy,dx) for dy in range(-1,2) for dx in range(-1,2) if (dy or dx) and (diag or abs(dy)+abs(dx)==1)]
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=value or (r,c) in seen: continue
            comp=[]; q=[(r,c)]; seen.add((r,c))
            while q:
                y,x=q.pop();comp.append((y,x))
                for dy,dx in neigh:
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and g[yy][xx]==value and (yy,xx) not in seen:
                        seen.add((yy,xx));q.append((yy,xx))
            comps.append(comp)
    return comps

