def outline_region(g, region, adj=8):
    h,w=len(g),len(g[0]); pred=set(); steps=[(dy,dx) for dy in range(-1,2) for dx in range(-1,2) if (dy or dx) and (adj==8 or abs(dy)+abs(dx)==1)]
    comps1=component_labels(g,1,diag=False); boundary1=set()
